function Card({ title, children }) {
  return <div><b>{title}:</b> {children}</div>;
}

function App() {
  return <Card title="Course">React Basics</Card>;
}

function App() {
  const letters = ["A", "B", "C"];
  return (
    <ul>
      {letters.map(l => <li key={l}>{l}</li>)}
    </ul>
  );
}

function Inbox({ count }) {
  return <div>{count && <p>You have messages</p>}</div>;
}
